import './style.css'
import {
  RANKS,
  cardRank,
  cardSuit,
  randomHoleCards,
} from './equity/cards'
import { calcExact, calcMonteCarlo } from './equity/client'
import {
  PRESET_RANGES,
  cellLabel,
  cloneMatrix,
  emptyMatrix,
  matrixComboCount,
  matrixSelectedCount,
  matrixToCombos,
  matrixToText,
  parseRangeText,
  type RangeMatrix,
} from './equity/range'

type Mode = 'hand' | 'range'

interface SessionStats {
  rounds: number
  hits: number
  sumAbsError: number
  equityRounds: number
}

interface TrainRange {
  id: string
  name: string
  text: string
  enabled: boolean
}

const app = document.querySelector<HTMLDivElement>('#app')!

let mode: Mode = 'hand'
let hero: [number, number] = [0, 1]
let villain: [number, number] = [2, 3]
let rangeMatrix: RangeMatrix = emptyMatrix()
let activeRangeName = ''
let trainingPool: TrainRange[] = PRESET_RANGES.map((p, i) => ({
  id: `preset-${i}`,
  name: p.name,
  text: p.text,
  enabled: true,
}))
let nextCustomId = 1
let revealed = false
let calculating = false

const stats: SessionStats = { rounds: 0, hits: 0, sumAbsError: 0, equityRounds: 0 }

const SUIT_SVG = [
  // clubs — 3 disques + tige (silhouette carte à jouer)
  `<svg viewBox="0 0 24 24" aria-hidden="true">
    <circle cx="12" cy="6.6" r="4.15"/>
    <circle cx="7.55" cy="12.15" r="4.15"/>
    <circle cx="16.45" cy="12.15" r="4.15"/>
    <path d="M11.15 14.2h1.7v5.35h1.85V21H9.3v-1.45h1.85z"/>
  </svg>`,
  // diamonds
  `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.2 19.2 12 12 21.8 4.8 12 12 2.2z"/></svg>`,
  // hearts
  `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.6S3.5 14.2 3.5 8.8C3.5 5.9 5.7 3.8 8.5 3.8c1.7 0 3.2.9 3.5 2.3.3-1.4 1.8-2.3 3.5-2.3 2.8 0 5 2.1 5 5 0 5.4-8.5 11.8-8.5 11.8z"/></svg>`,
  // spades
  `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.4C8.2 6.6 5 10.1 5 13.2c0 2.6 1.8 4.4 4.1 4.4 1 0 1.9-.4 2.5-1v2.7H10c-.4 0-.7.3-.7.7s.3.7.7.7h4c.4 0 .7-.3.7-.7s-.3-.7-.7-.7h-1.6V16.6c.6.6 1.5 1 2.5 1 2.3 0 4.1-1.8 4.1-4.4 0-3.1-3.2-6.6-7-10.8z"/></svg>`,
] as const

function renderCard(id: number, delay = 0, fanIndex = 0): string {
  const rank = RANKS[cardRank(id)]!
  const suit = cardSuit(id)
  const red = suit === 1 || suit === 2
  const svg = SUIT_SVG[suit]!
  return `<article class="pc ${red ? 'pc--red' : 'pc--black'} pc--fan-${fanIndex}" style="--deal-delay:${delay}ms" aria-label="${rank}${['♣', '♦', '♥', '♠'][suit]}">
    <div class="pc__face">
      <div class="pc__corner pc__corner--tl">
        <span class="pc__rank">${rank}</span>
        <span class="pc__mini">${svg}</span>
      </div>
      <div class="pc__center">${svg}</div>
      <div class="pc__corner pc__corner--br">
        <span class="pc__rank">${rank}</span>
        <span class="pc__mini">${svg}</span>
      </div>
    </div>
  </article>`
}

function mount(): void {
  app.innerHTML = `
    <header class="topbar">
      <div class="brand">
        <h1>Équité all-in</h1>
      </div>
      <div class="stats">
        <div class="stat">n<strong id="stat-rounds">0</strong></div>
        <div class="stat">hit<strong id="stat-acc">—</strong></div>
        <div class="stat" id="stat-err-wrap">err<strong id="stat-err">—</strong></div>
      </div>
    </header>

    <div class="layout">
      <section class="panel">
        <h2>Table</h2>
        <div class="mode-row">
          <button type="button" class="mode-btn active" data-mode="hand">Main / main</button>
          <button type="button" class="mode-btn" data-mode="range">Main / range</button>
        </div>

        <div class="matchup">
          <div class="matchup-side">
            <div class="matchup-label">Hero</div>
            <div class="hole-cards" id="hero-cards"></div>
          </div>
          <div class="vs-pill">vs</div>
          <div class="matchup-side">
            <div class="matchup-label" id="villain-label">Villain</div>
            <div class="hole-cards" id="villain-cards"></div>
          </div>
        </div>

        <div class="guess-block" id="equity-guess">
          <div class="matchup-label">Équité hero</div>
          <div class="slider-block">
            <div class="slider-value"><span id="guess-display">50.0</span><small>%</small></div>
            <input id="guess" class="guess-slider" type="range" min="0" max="100" step="0.5" value="50" />
            <div class="slider-scale"><span>0</span><span>50</span><span>100</span></div>
          </div>
          <div class="actions">
            <button type="button" class="btn btn-primary" id="btn-check">Valider</button>
            <button type="button" class="btn btn-ghost" id="btn-next">Suivant</button>
          </div>
          <div class="tolerance">
            <label>Tol. ± <input id="tol" type="number" min="0.5" max="20" step="0.5" value="3" /> %</label>
            <label class="mc-iters" id="mc-iters-wrap">MC <input id="mc-iters" type="number" min="5000" max="500000" step="5000" value="100000" /></label>
          </div>
        </div>

        <div class="progress" id="progress" hidden><span></span></div>
        <div class="result" id="result"></div>
      </section>

      <section class="panel range-panel" id="range-panel">
        <h2>Pool de ranges</h2>
        <p class="range-pool-intro">Coche les ranges contre lesquelles t’entraîner.</p>
        <div class="range-pool" id="range-pool"></div>
        <div class="range-pool-actions">
          <button type="button" class="btn-mini" id="btn-pool-all">Tout</button>
          <button type="button" class="btn-mini" id="btn-pool-none">Rien</button>
        </div>
        <div class="range-add">
          <select id="preset">
            <option value="">+ Preset…</option>
            ${PRESET_RANGES.map((p) => `<option value="${p.text}">${p.name}</option>`).join('')}
          </select>
          <input id="custom-range" class="range-add-input" type="text" spellcheck="false" placeholder="ou texte Equilab…" />
          <button type="button" class="btn-mini" id="btn-pool-add">Ajouter</button>
        </div>
        <p class="range-hint" id="pool-hint"></p>
      </section>
    </div>
  `

  bind()
  renderPool()
  updateModeUI()
  dealSpot(true)
}

function $(id: string): HTMLElement {
  return document.getElementById(id)!
}

function bind(): void {
  document.querySelectorAll<HTMLButtonElement>('.mode-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      mode = btn.dataset.mode as Mode
      updateModeUI()
      dealSpot(true)
    })
  })

  $('btn-next').addEventListener('click', () => dealSpot(true))
  $('btn-check').addEventListener('click', () => void submitGuess())
  $('guess').addEventListener('input', syncGuessDisplay)
  $('guess').addEventListener('keydown', (e) => {
    if ((e as KeyboardEvent).key === 'Enter') void submitGuess()
  })
  syncGuessDisplay()

  $('preset').addEventListener('change', (e) => {
    const select = e.target as HTMLSelectElement
    const text = select.value
    const name = select.selectedOptions[0]?.textContent?.trim() || text
    select.value = ''
    if (!text) return
    addRangeToPool(text, name)
  })

  $('btn-pool-all').addEventListener('click', () => {
    for (const r of trainingPool) r.enabled = true
    renderPool()
  })

  $('btn-pool-none').addEventListener('click', () => {
    for (const r of trainingPool) r.enabled = false
    renderPool()
  })

  $('btn-pool-add').addEventListener('click', () => {
    const input = $('custom-range') as HTMLInputElement
    addRangeToPool(input.value.trim())
    input.value = ''
  })

  $('custom-range').addEventListener('keydown', (e) => {
    if ((e as KeyboardEvent).key !== 'Enter') return
    const input = $('custom-range') as HTMLInputElement
    addRangeToPool(input.value.trim())
    input.value = ''
  })

  $('range-pool').addEventListener('click', (e) => {
    const target = e.target as HTMLElement
    const removeBtn = target.closest('[data-remove]') as HTMLElement | null
    if (removeBtn) {
      const id = removeBtn.dataset.remove!
      trainingPool = trainingPool.filter((r) => r.id !== id)
      renderPool()
      return
    }
    const chip = target.closest('[data-range-id]') as HTMLElement | null
    if (!chip) return
    const id = chip.dataset.rangeId!
    const entry = trainingPool.find((r) => r.id === id)
    if (!entry) return
    entry.enabled = !entry.enabled
    renderPool()
  })
}

function addRangeToPool(text: string, preferredName?: string): void {
  if (!text) {
    $('pool-hint').textContent = 'Entre une range (notation Equilab).'
    $('pool-hint').classList.add('err')
    return
  }
  const parsed = parseRangeText(text)
  if (parsed.error || matrixSelectedCount(parsed.matrix) === 0) {
    $('pool-hint').textContent = parsed.error || 'Range vide.'
    $('pool-hint').classList.add('err')
    return
  }
  const normalized = matrixToText(parsed.matrix)
  const existing = trainingPool.find((r) => r.text === normalized || r.text === text)
  if (existing) {
    existing.enabled = true
    renderPool()
    $('pool-hint').textContent = `"${existing.name}" déjà dans le pool — activée.`
    $('pool-hint').classList.remove('err')
    return
  }
  const name =
    preferredName && preferredName !== text
      ? preferredName
      : normalized.length > 28
        ? `${normalized.slice(0, 26)}…`
        : normalized
  trainingPool.push({
    id: `custom-${nextCustomId++}`,
    name,
    text: normalized,
    enabled: true,
  })
  renderPool()
}

function updateModeUI(): void {
  document.querySelectorAll('.mode-btn').forEach((b) => {
    b.classList.toggle('active', (b as HTMLElement).dataset.mode === mode)
  })
  const isRange = mode === 'range'
  $('range-panel').classList.toggle('hidden', mode === 'hand')
  $('mc-iters-wrap').style.display = isRange ? '' : 'none'
  $('villain-label').textContent = mode === 'hand' ? 'Villain' : 'Range'
  document.querySelector('.matchup')?.classList.toggle('matchup--range', isRange)
}

function enabledRanges(): TrainRange[] {
  return trainingPool.filter((r) => r.enabled)
}

function renderPool(): void {
  const pool = $('range-pool')
  pool.innerHTML = trainingPool
    .map((r) => {
      const custom = r.id.startsWith('custom-')
      return `<button type="button" class="range-chip${r.enabled ? ' on' : ''}" data-range-id="${r.id}" title="${r.text}">
        <span class="range-chip-check" aria-hidden="true">${r.enabled ? '✓' : ''}</span>
        <span class="range-chip-name">${r.name}</span>
        ${custom ? `<span class="range-chip-remove" data-remove="${r.id}" title="Retirer">×</span>` : ''}
      </button>`
    })
    .join('')

  const n = enabledRanges().length
  const hint = $('pool-hint')
  hint.classList.toggle('err', n === 0)
  hint.textContent =
    n === 0
      ? 'Sélectionne au moins une range.'
      : `${n} range${n > 1 ? 's' : ''} · tirage aléatoire`
}

function applyRangeText(text: string, name: string): boolean {
  const parsed = parseRangeText(text)
  if (parsed.error || matrixSelectedCount(parsed.matrix) === 0) return false
  rangeMatrix = parsed.matrix
  activeRangeName = name
  return true
}

function pickTrainingRange(): TrainRange | null {
  const pool = enabledRanges()
  if (pool.length === 0) return null
  return pool[(Math.random() * pool.length) | 0]!
}

function syncGuessDisplay(): void {
  const guess = $('guess') as HTMLInputElement
  const value = Number(guess.value)
  $('guess-display').textContent = value.toFixed(1)
  const pct = ((value - Number(guess.min)) / (Number(guess.max) - Number(guess.min))) * 100
  guess.style.setProperty('--guess-pct', `${pct}%`)
}

function dealSpot(resetResult: boolean): void {
  if (calculating) return
  revealed = false

  if (mode === 'hand') {
    hero = randomHoleCards()
    villain = randomHoleCards(hero)
    activeRangeName = ''
  } else {
    const picked = pickTrainingRange()
    if (!picked) {
      renderPool()
      $('result').classList.add('show')
      $('result').innerHTML =
        '<div class="delta bad">Sélectionne au moins une range d’entraînement.</div>'
      return
    }
    if (!applyRangeText(picked.text, picked.name)) {
      $('result').classList.add('show')
      $('result').innerHTML = `<div class="delta bad">Range invalide : ${picked.name}</div>`
      return
    }

    let ok = false
    for (let attempt = 0; attempt < 60; attempt++) {
      hero = randomHoleCards()
      if (matrixToCombos(rangeMatrix, hero).length > 0) {
        ok = true
        break
      }
    }
    if (!ok) {
      $('result').classList.add('show')
      $('result').innerHTML =
        '<div class="delta bad">Impossible de tirer un hero compatible avec cette range.</div>'
      return
    }
    villain = hero
  }

  paintCards()

  const guess = $('guess') as HTMLInputElement
  guess.value = '50'
  guess.disabled = false
  syncGuessDisplay()
  ;($('btn-check') as HTMLButtonElement).disabled = false
  $('progress').hidden = true
  if (resetResult) {
    $('result').classList.remove('show')
    $('result').innerHTML = ''
  }
}

function renderRangeFace(): string {
  const name = activeRangeName || 'Range'
  const combos = matrixComboCount(rangeMatrix, hero)
  let cells = ''
  for (let row = 0; row < 13; row++) {
    for (let col = 0; col < 13; col++) {
      const on = rangeMatrix[row]![col]
      const kind = row === col ? 'pair' : col > row ? 'suited' : 'offsuit'
      const lab = cellLabel(row, col)
      cells += `<span class="mini-cell ${kind}${on ? ' on' : ''}" title="${lab}">${lab}</span>`
    }
  }
  return `<div class="range-face" aria-label="Range villain ${name}">
    <div class="mini-matrix">${cells}</div>
    <div class="range-face__meta">${name} · ${combos} combos</div>
  </div>`
}

function paintCards(): void {
  $('hero-cards').innerHTML = renderCard(hero[0], 0, 0) + renderCard(hero[1], 70, 1)

  if (mode === 'hand') {
    $('villain-cards').innerHTML = renderCard(villain[0], 140, 0) + renderCard(villain[1], 210, 1)
  } else {
    $('villain-cards').innerHTML = renderRangeFace()
  }
}

async function runMonteCarloEquity(
  onProgress: (done: number, total: number) => void,
  iterations: number,
): Promise<{ equity: number; detail: string }> {
  const combos = matrixToCombos(cloneMatrix(rangeMatrix), hero)
  if (combos.length === 0) throw new Error('Aucun combo villain possible (card removal).')
  const res = await calcMonteCarlo(hero, combos, iterations, onProgress)
  return {
    equity: res.equity,
    detail: `Monte Carlo · ${res.iterations.toLocaleString('fr-FR')} it. · ±${res.stdError.toFixed(2)}% (1σ) · ${res.elapsedMs.toFixed(0)} ms · ${combos.length} combos`,
  }
}

async function submitGuess(): Promise<void> {
  if (calculating || revealed) return
  const guessEl = $('guess') as HTMLInputElement
  const guess = Number(guessEl.value)
  if (!Number.isFinite(guess) || guess < 0 || guess > 100) return

  calculating = true
  guessEl.disabled = true
  ;($('btn-check') as HTMLButtonElement).disabled = true
  const progress = $('progress')
  const bar = progress.querySelector('span')!
  progress.hidden = false
  bar.style.width = '0%'

  const onProgress = (done: number, total: number) => {
    bar.style.width = `${Math.min(100, (done / total) * 100)}%`
  }

  try {
    let equity: number
    let detail: string

    if (mode === 'hand') {
      const res = await calcExact(hero, villain, onProgress)
      equity = res.equity
      detail = `Exact · ${res.boards.toLocaleString('fr-FR')} boards · ${res.elapsedMs.toFixed(0)} ms · W ${res.win.toLocaleString('fr-FR')} / T ${res.tie.toLocaleString('fr-FR')} / L ${res.lose.toLocaleString('fr-FR')}`
    } else {
      const iters = Math.max(5_000, Number(($('mc-iters') as HTMLInputElement).value) || 100_000)
      ;({ equity, detail } = await runMonteCarloEquity(onProgress, iters))
    }

    bar.style.width = '100%'
    revealed = true
    showResult(guess, equity, detail)
  } catch (err) {
    $('result').classList.add('show')
    $('result').innerHTML = `<div class="delta bad">${err instanceof Error ? err.message : String(err)}</div>`
    guessEl.disabled = false
    ;($('btn-check') as HTMLButtonElement).disabled = false
  } finally {
    calculating = false
  }
}

function showResult(guess: number, equity: number, detail: string): void {
  const tol = Math.max(0.5, Number(($('tol') as HTMLInputElement).value) || 3)
  const absErr = Math.abs(guess - equity)
  const hit = absErr <= tol

  stats.rounds++
  stats.equityRounds++
  stats.sumAbsError += absErr
  if (hit) stats.hits++
  updateStats()

  let grade = 'bad'
  let label = 'Loin'
  if (absErr <= tol) {
    grade = 'good'
    label = 'OK'
  } else if (absErr <= tol * 2) {
    grade = 'mid'
    label = 'Proche'
  } else {
    grade = 'bad'
    label = 'Loin'
  }

  const res = $('result')
  res.classList.add('show')
  res.innerHTML = `
    <div class="equity">${equity.toFixed(2)}%</div>
    <div class="delta ${grade}">${label} · Δ ${absErr.toFixed(2)} (guess ${guess.toFixed(1)})</div>
    <div class="meta">${detail}</div>
  `
}

function updateStats(): void {
  $('stat-rounds').textContent = String(stats.rounds)
  if (stats.rounds === 0) {
    $('stat-acc').textContent = '—'
    $('stat-err').textContent = '—'
    return
  }
  $('stat-acc').textContent = `${((stats.hits / stats.rounds) * 100).toFixed(0)}%`
  $('stat-err').textContent =
    stats.equityRounds > 0 ? `${(stats.sumAbsError / stats.equityRounds).toFixed(1)}` : '—'
}

mount()
