import type { WorkerRequest, WorkerResponse } from './equity.worker'
import type { EquityResult } from './exact'
import type { MonteCarloResult } from './montecarlo'

type Result = EquityResult | MonteCarloResult

let worker: Worker | null = null
let nextId = 1

function getWorker(): Worker {
  if (!worker) {
    worker = new Worker(new URL('./equity.worker.ts', import.meta.url), { type: 'module' })
  }
  return worker
}

function runJob(payload: WorkerRequest, onProgress?: (done: number, total: number) => void): Promise<Result> {
  const w = getWorker()

  return new Promise((resolve, reject) => {
    const handler = (ev: MessageEvent<WorkerResponse>) => {
      const msg = ev.data
      if (msg.id !== payload.id) return
      if (msg.type === 'progress') {
        onProgress?.(msg.done, msg.total)
        return
      }
      w.removeEventListener('message', handler)
      if (msg.type === 'error') reject(new Error(msg.message))
      else resolve(msg.result)
    }
    w.addEventListener('message', handler)
    w.postMessage(payload)
  })
}

export function calcExact(
  hero: [number, number],
  villain: [number, number],
  onProgress?: (done: number, total: number) => void,
): Promise<EquityResult> {
  const id = nextId++
  return runJob({ id, type: 'exact', hero, villain }, onProgress) as Promise<EquityResult>
}

export function calcMonteCarlo(
  hero: [number, number],
  combos: number[][],
  iterations: number,
  onProgress?: (done: number, total: number) => void,
): Promise<MonteCarloResult> {
  const id = nextId++
  return runJob(
    { id, type: 'montecarlo', hero, combos, iterations },
    onProgress,
  ) as Promise<MonteCarloResult>
}
