/** Rangs : 0=2 … 12=A. Couleurs : 0=c, 1=d, 2=h, 3=s. Carte = rank + suit*13 (0–51). */

export const RANKS = ['2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K', 'A'] as const
export const SUITS = ['c', 'd', 'h', 's'] as const
export const SUIT_SYMBOLS = ['♣', '♦', '♥', '♠'] as const
export const SUIT_COLORS = ['#1a7a4c', '#c45c2a', '#c62828', '#1a1a1a'] as const

export type RankChar = (typeof RANKS)[number]
export type SuitChar = (typeof SUITS)[number]

export function cardId(rank: number, suit: number): number {
  return rank + suit * 13
}

export function cardRank(id: number): number {
  return id % 13
}

export function cardSuit(id: number): number {
  return (id / 13) | 0
}

export function parseCard(str: string): number {
  const s = str.trim()
  if (s.length < 2) throw new Error(`Carte invalide: ${str}`)
  const rankChar = s[0]!.toUpperCase()
  const suitChar = s[1]!.toLowerCase()
  const rank = RANKS.indexOf(rankChar as RankChar)
  const suit = SUITS.indexOf(suitChar as SuitChar)
  if (rank < 0 || suit < 0) throw new Error(`Carte invalide: ${str}`)
  return cardId(rank, suit)
}

export function formatCard(id: number): string {
  return `${RANKS[cardRank(id)]}${SUITS[cardSuit(id)]}`
}

export function formatCardPretty(id: number): string {
  return `${RANKS[cardRank(id)]}${SUIT_SYMBOLS[cardSuit(id)]}`
}

export function fullDeck(): number[] {
  const d: number[] = []
  for (let i = 0; i < 52; i++) d.push(i)
  return d
}

export function remainingDeck(dead: number[]): number[] {
  const used = new Uint8Array(52)
  for (const c of dead) used[c] = 1
  const out: number[] = []
  for (let i = 0; i < 52; i++) if (!used[i]) out.push(i)
  return out
}

/** Toutes les combos hole cards d’une classe 169 (ex. AKs, AKo, AA). */
export function expandHandClass(label: string): number[][] {
  const t = label.trim().toUpperCase()
  if (t.length === 2 && t[0] === t[1]) {
    const r = RANKS.indexOf(t[0] as RankChar)
    if (r < 0) return []
    const combos: number[][] = []
    for (let s1 = 0; s1 < 4; s1++) {
      for (let s2 = s1 + 1; s2 < 4; s2++) {
        combos.push([cardId(r, s1), cardId(r, s2)])
      }
    }
    return combos
  }
  if (t.length !== 3) return []
  const r1 = RANKS.indexOf(t[0] as RankChar)
  const r2 = RANKS.indexOf(t[1] as RankChar)
  const suited = t[2] === 'S'
  const offsuit = t[2] === 'O'
  if (r1 < 0 || r2 < 0 || r1 === r2 || (!suited && !offsuit)) return []
  const hi = Math.max(r1, r2)
  const lo = Math.min(r1, r2)
  const combos: number[][] = []
  if (suited) {
    for (let s = 0; s < 4; s++) combos.push([cardId(hi, s), cardId(lo, s)])
  } else {
    for (let s1 = 0; s1 < 4; s1++) {
      for (let s2 = 0; s2 < 4; s2++) {
        if (s1 !== s2) combos.push([cardId(hi, s1), cardId(lo, s2)])
      }
    }
  }
  return combos
}

export function randomHoleCards(dead: number[] = []): [number, number] {
  const deck = remainingDeck(dead)
  const i = (Math.random() * deck.length) | 0
  const c1 = deck[i]!
  deck[i] = deck[deck.length - 1]!
  deck.pop()
  const j = (Math.random() * deck.length) | 0
  return [c1, deck[j]!]
}

export function handClassFromCards(c1: number, c2: number): string {
  const r1 = cardRank(c1)
  const r2 = cardRank(c2)
  const s1 = cardSuit(c1)
  const s2 = cardSuit(c2)
  if (r1 === r2) return `${RANKS[r1]}${RANKS[r2]}`
  const hi = Math.max(r1, r2)
  const lo = Math.min(r1, r2)
  const suffix = s1 === s2 ? 's' : 'o'
  return `${RANKS[hi]}${RANKS[lo]}${suffix}`
}
