import { RANKS, expandHandClass, type RankChar } from './cards'

/** Matrice 13×13 : [row][col] avec row/col = A…2 (index 0 = A). */
export type RangeMatrix = boolean[][]

export function emptyMatrix(): RangeMatrix {
  return Array.from({ length: 13 }, () => Array<boolean>(13).fill(false))
}

export function cloneMatrix(m: RangeMatrix): RangeMatrix {
  return m.map((row) => row.slice())
}

/** Label Equilab d’une cellule (r,c) en indices A=0…2=12. */
export function cellLabel(row: number, col: number): string {
  const r1 = 12 - row
  const r2 = 12 - col
  if (row === col) return `${RANKS[r1]}${RANKS[r2]}`
  if (col > row) return `${RANKS[r1]}${RANKS[r2]}s` // dessus = suited
  return `${RANKS[r2]}${RANKS[r1]}o` // dessous = offsuit (plus haute rangée = plus haut rang)
}

/**
 * Convention matrice type Equilab :
 * - Diagonale : paires AA…22
 * - Au-dessus : suited (AKs…)
 * - En-dessous : offsuit (AKo…)
 * Indices d’affichage : ligne/colonne 0 = A … 12 = 2
 */
export function setCell(m: RangeMatrix, row: number, col: number, on: boolean): void {
  m[row]![col] = on
}

export function matrixToCombos(m: RangeMatrix, dead: number[] = []): number[][] {
  const deadSet = new Set(dead)
  const combos: number[][] = []
  for (let row = 0; row < 13; row++) {
    for (let col = 0; col < 13; col++) {
      if (!m[row]![col]) continue
      const label = cellLabel(row, col)
      for (const combo of expandHandClass(label)) {
        if (deadSet.has(combo[0]!) || deadSet.has(combo[1]!)) continue
        combos.push(combo)
      }
    }
  }
  return combos
}

export function matrixComboCount(m: RangeMatrix, dead: number[] = []): number {
  return matrixToCombos(m, dead).length
}

export function matrixSelectedCount(m: RangeMatrix): number {
  let n = 0
  for (let r = 0; r < 13; r++) for (let c = 0; c < 13; c++) if (m[r]![c]) n++
  return n
}

function rankIndexFromChar(ch: string): number {
  return RANKS.indexOf(ch.toUpperCase() as RankChar)
}

/** Parse une classe unique : AA, AKs, AKo, 76s… */
function parseAtom(atom: string): string[] {
  const a = atom.trim().toUpperCase().replace(/\s/g, '')
  if (!a) return []

  // Pair range: 99+, 22-77, JJ+
  const pairPlus = /^([2-9TJQKA])\1\+$/.exec(a)
  if (pairPlus) {
    const lo = rankIndexFromChar(pairPlus[1]!)
    const out: string[] = []
    for (let r = lo; r <= 12; r++) out.push(`${RANKS[r]}${RANKS[r]}`)
    return out
  }

  const pairRange = /^([2-9TJQKA])\1-([2-9TJQKA])\2$/.exec(a)
  if (pairRange) {
    let r1 = rankIndexFromChar(pairRange[1]!)
    let r2 = rankIndexFromChar(pairRange[2]!)
    if (r1 < r2) [r1, r2] = [r2, r1]
    const out: string[] = []
    for (let r = r2; r <= r1; r++) out.push(`${RANKS[r]}${RANKS[r]}`)
    return out
  }

  const pair = /^([2-9TJQKA])\1$/.exec(a)
  if (pair) return [a]

  // Suited/offsuit plus: ATs+, KJs+, ATo+
  const nonPairPlus = /^([2-9TJQKA])([2-9TJQKA])([SO])\+$/.exec(a)
  if (nonPairPlus) {
    const hi = rankIndexFromChar(nonPairPlus[1]!)
    const lo = rankIndexFromChar(nonPairPlus[2]!)
    const suf = nonPairPlus[3]!.toLowerCase()
    if (hi === lo) return []
    const top = Math.max(hi, lo)
    const bottom = Math.min(hi, lo)
    const out: string[] = []
    for (let r = bottom; r < top; r++) {
      out.push(`${RANKS[top]}${RANKS[r]}${suf}`)
    }
    return out
  }

  // Range suited/offsuit: ATs-A5s, KQo-KJo
  const nonPairRange = /^([2-9TJQKA])([2-9TJQKA])([SO])-([2-9TJQKA])([2-9TJQKA])\3$/.exec(a)
  if (nonPairRange) {
    const h1 = rankIndexFromChar(nonPairRange[1]!)
    const l1 = rankIndexFromChar(nonPairRange[2]!)
    const h2 = rankIndexFromChar(nonPairRange[4]!)
    const l2 = rankIndexFromChar(nonPairRange[5]!)
    const suf = nonPairRange[3]!.toLowerCase()
    if (h1 !== h2) return []
    const top = h1
    let aLo = Math.min(l1, l2)
    let bLo = Math.max(l1, l2)
    if (aLo >= top || bLo >= top) return []
    const out: string[] = []
    for (let r = aLo; r <= bLo; r++) out.push(`${RANKS[top]}${RANKS[r]}${suf}`)
    return out
  }

  const nonPair = /^([2-9TJQKA])([2-9TJQKA])([SO])$/.exec(a)
  if (nonPair) {
    const r1 = rankIndexFromChar(nonPair[1]!)
    const r2 = rankIndexFromChar(nonPair[2]!)
    const suf = nonPair[3]!.toLowerCase()
    if (r1 === r2) return []
    const hi = Math.max(r1, r2)
    const lo = Math.min(r1, r2)
    return [`${RANKS[hi]}${RANKS[lo]}${suf}`]
  }

  // Broadways shorthand without s/o: AK = AKs + AKo
  const both = /^([2-9TJQKA])([2-9TJQKA])$/.exec(a)
  if (both && both[1] !== both[2]) {
    const r1 = rankIndexFromChar(both[1]!)
    const r2 = rankIndexFromChar(both[2]!)
    const hi = Math.max(r1, r2)
    const lo = Math.min(r1, r2)
    return [`${RANKS[hi]}${RANKS[lo]}s`, `${RANKS[hi]}${RANKS[lo]}o`]
  }

  return []
}

/** Parse notation type Equilab : "QQ+, AKs, AKo, 76s-75s, JJ+" */
export function parseRangeText(text: string): { matrix: RangeMatrix; error?: string } {
  const matrix = emptyMatrix()
  const cleaned = text.replace(/\s+/g, '')
  if (!cleaned) return { matrix }

  const parts = cleaned.split(',')
  const labels = new Set<string>()

  for (const part of parts) {
    if (!part) continue
    const atoms = parseAtom(part)
    if (atoms.length === 0) {
      return { matrix: emptyMatrix(), error: `Segment invalide: "${part}"` }
    }
    for (const lab of atoms) labels.add(lab)
  }

  for (const lab of labels) {
    const cell = labelToCell(lab)
    if (cell) matrix[cell.row]![cell.col] = true
  }
  return { matrix }
}

export function labelToCell(label: string): { row: number; col: number } | null {
  const t = label.trim().toUpperCase()
  if (t.length === 2 && t[0] === t[1]) {
    const r = rankIndexFromChar(t[0]!)
    if (r < 0) return null
    const i = 12 - r
    return { row: i, col: i }
  }
  if (t.length !== 3) return null
  const r1 = rankIndexFromChar(t[0]!)
  const r2 = rankIndexFromChar(t[1]!)
  const suf = t[2]
  if (r1 < 0 || r2 < 0 || r1 === r2) return null
  const hi = Math.max(r1, r2)
  const lo = Math.min(r1, r2)
  const hiIdx = 12 - hi
  const loIdx = 12 - lo
  if (suf === 'S') return { row: hiIdx, col: loIdx } // above diagonal
  if (suf === 'O') return { row: loIdx, col: hiIdx } // below diagonal
  return null
}

export function matrixToText(m: RangeMatrix): string {
  const pairs: number[] = []
  const suited = new Map<number, number[]>()
  const offsuit = new Map<number, number[]>()

  for (let row = 0; row < 13; row++) {
    for (let col = 0; col < 13; col++) {
      if (!m[row]![col]) continue
      const lab = cellLabel(row, col)
      if (lab.length === 2) {
        pairs.push(rankIndexFromChar(lab[0]!))
      } else {
        const hi = rankIndexFromChar(lab[0]!)
        const lo = rankIndexFromChar(lab[1]!)
        const map = lab.endsWith('s') ? suited : offsuit
        if (!map.has(hi)) map.set(hi, [])
        map.get(hi)!.push(lo)
      }
    }
  }

  const parts: string[] = []
  pairs.sort((a, b) => b - a)
  parts.push(...compressRanks(pairs, (r) => `${RANKS[r]}${RANKS[r]}`, true))

  for (const [hi, los] of [...suited.entries()].sort((a, b) => b[0] - a[0])) {
    parts.push(...compressConnected(hi, [...new Set(los)], 's'))
  }
  for (const [hi, los] of [...offsuit.entries()].sort((a, b) => b[0] - a[0])) {
    parts.push(...compressConnected(hi, [...new Set(los)], 'o'))
  }

  return parts.join(', ')
}

function compressRanks(
  ranks: number[],
  fmt: (r: number) => string,
  allowPlus: boolean,
): string[] {
  if (ranks.length === 0) return []
  const uniq = [...new Set(ranks)].sort((a, b) => b - a)
  const out: string[] = []
  let i = 0
  while (i < uniq.length) {
    let j = i
    while (j + 1 < uniq.length && uniq[j]! - 1 === uniq[j + 1]) j++
    const hi = uniq[i]!
    const lo = uniq[j]!
    if (allowPlus && hi === 12 && j > i) {
      out.push(`${fmt(lo)}+`)
    } else if (j === i) {
      out.push(fmt(hi))
    } else if (allowPlus && hi === 12) {
      out.push(`${fmt(lo)}+`)
    } else {
      out.push(`${fmt(hi)}-${fmt(lo)}`)
    }
    i = j + 1
  }
  return out
}

function compressConnected(hi: number, los: number[], suf: 's' | 'o'): string[] {
  const out: string[] = []
  let i = 0
  const sorted = [...los].sort((a, b) => b - a)
  while (i < sorted.length) {
    let j = i
    while (j + 1 < sorted.length && sorted[j]! - 1 === sorted[j + 1]) j++
    const topLo = sorted[i]!
    const botLo = sorted[j]!
    if (j === i) {
      out.push(`${RANKS[hi]}${RANKS[topLo]}${suf}`)
    } else if (topLo === hi - 1) {
      // contiguous from just below hi down → plus notation
      out.push(`${RANKS[hi]}${RANKS[botLo]}${suf}+`)
    } else {
      out.push(`${RANKS[hi]}${RANKS[topLo]}${suf}-${RANKS[hi]}${RANKS[botLo]}${suf}`)
    }
    i = j + 1
  }
  return out
}

